const b = $json.body || {};
const action = String(b.action || '');
return { json: { action, name: String(b.name || '').slice(0, 100), password: String(b.password || '').slice(0, 200), token: String(b.token || '').slice(0, 128), candidate_id: Math.floor(Number(b.candidate_id) || 0), subject: String(b.subject || '').slice(0, 300), body_text: String(b.body || '').slice(0, 6000), stage: String(b.stage || '').slice(0, 30), notes: String(b.notes || '').slice(0, 4000), next_action: String(b.next_action || '').slice(0, 300), notification_id: Math.floor(Number(b.notification_id) || 0), reply_to_id: Math.floor(Number(b.reply_to_id) || 0) } };

const AU = /,\s*Australia\s*$/i;
const ST = /\s+(SA|NSW|VIC|QLD|WA|NT|TAS|ACT)\s+\d{4}.*$/i;
const rows = $input.all().map(i => i.json);
rows.forEach(r => { if (!r.suburb) { const a = (r.address || '').replace(AU, ''); const p = a.split(','); r.suburb = p.length < 2 ? '' : p[p.length - 1].replace(ST, '').trim(); } });
return [{ json: { out: JSON.stringify({ ok: true, leads: rows }) } }];

const p = $('Parse Request').item.json;
const a = $json;
let route = 'fail';
let response = { ok: false, error: 'unauthorized' };
if (p.action === 'login') {
  route = 'auth';
  response = a.new_token ? { ok: true, token: a.new_token } : { ok: false, error: 'invalid name or password' };
} else if (a.auth_user) {
  if (['leads', 'draft', 'save', 'send', 'crm_add', 'crm_list', 'crm_stage', 'crm_timeline', 'crm_notes', 'crm_next_action', 'system_status', 'notifications_list', 'notifications_mark_read', 'stats', 'crm_replies', 'crm_reply_send', 'website_quotes_list'].indexOf(p.action) >= 0) { route = p.action; } else { response = { ok: false, error: 'unknown action' }; }
}
return { json: { route, response, auth_user: a.auth_user || null, candidate_id: p.candidate_id, subject: p.subject, body_text: p.body_text, stage: p.stage, notes: p.notes, next_action: p.next_action, notification_id: p.notification_id, reply_to_id: p.reply_to_id } };

const AU = /,\s*Australia\s*$/i;
const ST = /\s+(SA|NSW|VIC|QLD|WA|NT|TAS|ACT)\s+\d{4}.*$/i;
const rows = $input.all().map(i => i.json).filter(r => r && r.candidate_id != null);
rows.forEach(r => { if (!r.suburb) { const a = (r.address || '').replace(AU, ''); const p = a.split(','); r.suburb = p.length < 2 ? '' : p[p.length - 1].replace(ST, '').trim(); } });
return [{ json: { out: JSON.stringify({ ok: true, records: rows }) } }];

const j = $json;
const FIVE_MIN_MS = 5 * 60 * 1000;
const now = Date.now();
function colorFor(row) {
  if (!row || !row.active) return 'red';
  if (row.last_failed_at && (!row.last_success_at || new Date(row.last_failed_at) > new Date(row.last_success_at))) return 'red';
  if (row.last_status === 'error' || row.last_status === 'crashed') return 'yellow';
  return 'green';
}
const workflows = (j.workflows || []).map(w => ({ ...w, health: colorFor(w) }));
const byName = {};
workflows.forEach(w => { byName[w.name] = w; });
const imapRow = byName['Reply Detection Engine'];
const imapHealth = imapRow ? colorFor(imapRow) : 'red';
const smtpLastSend = j.last_smtp_send_at;
const smtpHealth = smtpLastSend ? 'green' : 'yellow';
const emailOps = {
  imap: { status: imapRow && imapRow.active ? 'connected' : 'disconnected', mailbox: 'kqualitycleaningservices@gmail.com', last_check: imapRow ? imapRow.last_stopped_at : null, health: imapHealth },
  smtp: { status: 'connected', sender_name: 'KQuality Cleaning Services', sender_email: 'kqualitycleaningservices@gmail.com', last_successful_send: smtpLastSend, health: smtpHealth },
  reply_detection: { total: Number(j.replies_total || 0), today: Number(j.replies_today || 0), unmatched: Number(j.replies_unmatched || 0), last_reply_at: j.last_reply_at }
};
const health = {
  infrastructure: { vps: 'green', postgresql: 'green', docker: 'green', browserless: 'green', n8n: 'green', caddy: 'green' },
  email: { smtp: smtpHealth, imap: imapHealth, gmail_filters: 'green' },
  automation: {}
};
const engineMap = { 'Opportunity Discovery Engine': 'discovery', 'Lead Intelligence Engine': 'intelligence', 'Lead Qualification Engine': 'qualification', 'Personalized Outreach Engine': 'outreach', 'Daily Automated Outreach Engine': 'daily_outreach', 'Outreach Follow-up Engine': 'followup', 'Reply Detection Engine': 'reply_detection' };
Object.keys(engineMap).forEach(name => { const row = byName[name]; health.automation[engineMap[name]] = row ? colorFor(row) : 'red'; });
return { json: { out: JSON.stringify({ ok: true, workflows, email_ops: emailOps, health }) } };

const j = $json;
const won = Number(j.won || 0);
const total = Number(j.crm_total || 0);
const conversion = total > 0 ? ((won / total) * 100).toFixed(1) + '%' : 'N/A';
return { json: { out: JSON.stringify({ ok: true, stats: { leads_discovered: Number(j.leads_discovered||0), leads_enriched: Number(j.leads_enriched||0), qualified_hot: Number(j.qualified_hot||0), qualified_warm: Number(j.qualified_warm||0), qualified_cold: Number(j.qualified_cold||0), drafts_generated: Number(j.drafts_generated||0), emails_sent: Number(j.emails_sent||0), replies_received: Number(j.replies_received||0), active_followups: Number(j.active_followups||0), meetings_booked: Number(j.meetings_booked||0), won, conversion_rate: conversion, daily_auto_sent_today: Number(j.daily_auto_sent_today||0), daily_auto_sent_total: Number(j.daily_auto_sent_total||0) } }) } };

const rows = $json.rows || [];
const inbound = rows.filter(r => r.direction === 'inbound');
return { json: { out: JSON.stringify({ ok: true, messages: rows, reply_count: inbound.length, last_reply_at: inbound.length ? inbound[inbound.length - 1].ts : null }) } };
